import React, { useState, useRef, useEffect } from 'react'
import { View, Text, TouchableOpacity, Dimensions, Animated } from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';


export function Alert() {
    const { selectedNumber, alertMessage, setSelectedNumber, alertActive, setAlertActive, shoppingCartItem } = useContexState();

    const tempShoppingCartItem = [...shoppingCartItem];
    const index = tempShoppingCartItem.indexOf(Number(selectedNumber));
    const fadeAnim = useRef(new Animated.Value(0.5)).current;

    function fadeIn() {
        Animated.timing(fadeAnim, {
            toValue: 1,
            duration: 700,
        } as Animated.TimingAnimationConfig).start(() => {

        });
    }

    useEffect(() => { fadeIn() }, [])

    return (alertActive ? <>
        <TouchableOpacity onPress={() => {
            setAlertActive(false);
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />

        <Animated.View style={[styles.container, { transform: [{ scale: fadeAnim }] }]} >
            <Text style={styles.listText}>{alertMessage}</Text>
        </Animated.View>
    </> : null
    );
};
